import re, os

# Find all .rs files in src/
for root, dirs, files in os.walk('src'):
    for f in files:
        if f.endswith('.rs'):
            path = os.path.join(root, f)
            with open(path) as fh:
                lines = fh.readlines()
            in_test = False
            brace_depth = 0
            for i, line in enumerate(lines, 1):
                # Track if we're in a #[cfg(test)] mod
                stripped = line.strip()
                if '#[cfg(test)]' in stripped:
                    in_test = True
                if in_test:
                    brace_depth += line.count('{') - line.count('}')
                    if brace_depth <= 0 and i > 1:
                        in_test = False
                        brace_depth = 0
                if not in_test and '.unwrap()' in line:
                    print(f'{path}:{i}: {line.rstrip()}')
